class Rectangle {
    int width, height;
    void setWidth(int w)  { this.width = w; }
    void setHeight(int h) { this.height = h; }
    int area() { return width * height; }
}

class Square extends Rectangle {
    // Square must keep width == height
    void setWidth(int w)  { this.width = w; this.height = w; }  // LSP violation!
    void setHeight(int h) { this.height = h; this.width = h; }  // breaks caller expectations
}

// This code breaks when Rectangle is replaced by Square
void resize(Rectangle r) {
    r.setWidth(5);
    r.setHeight(10);
    assert r.area() == 50; // fails for Square — area is 100!
}

// Fix: both implement Shape independently, no inheritance relationship
interface Shape { int area(); }

class Rectangle implements Shape {
    int width, height;
    Rectangle(int w, int h) { this.width = w; this.height = h; }
    public int area() { return width * height; }
}

class Square implements Shape {
    int side;
    Square(int s) { this.side = s; }
    public int area() { return side * side; }
}
// Now both are shapes but neither misrepresents the other

class Bird {
    void fly() { System.out.println("flying"); }
}

class Penguin extends Bird {
    void fly() {
        throw new UnsupportedOperationException("Penguins cannot fly!");
    }
}

// Caller breaks at runtime
void makeFly(Bird b) {
    b.fly(); // works for Bird, explodes for Penguin
}
// Penguin claims to be a Bird but cannot substitute for one safely
